solution.javascript:
function minCostConnectPoints(points) {
  const n = points.length;
  const visited = new Set([0]);
  let total = 0;
  const dist = Array(n).fill(Infinity);
  for (let i = 1; i < n; i++) dist[i] = Math.abs(points[0][0]-points[i][0]) + Math.abs(points[0][1]-points[i][1]);
  while (visited.size < n) {
    let minD = Infinity, minI = -1;
    for (let i = 0; i < n; i++) if (!visited.has(i) && dist[i] < minD) { minD = dist[i]; minI = i; }
    visited.add(minI); total += minD;
    for (let i = 0; i < n; i++) if (!visited.has(i)) dist[i] = Math.min(dist[i], Math.abs(points[minI][0]-points[i][0]) + Math.abs(points[minI][1]-points[i][1]));
  }
  return total;
}

solution.cpp:
int minCostConnectPoints(vector<vector<int>>& points) {
    int n = points.size();
    vector<bool> vis(n); vis[0] = true;
    vector<int> dist(n, INT_MAX);
    for (int i = 1; i < n; i++) dist[i] = abs(points[0][0]-points[i][0]) + abs(points[0][1]-points[i][1]);
    int total = 0;
    for (int _ = 0; _ < n - 1; _++) {
        int minD = INT_MAX, minI = -1;
        for (int i = 0; i < n; i++) if (!vis[i] && dist[i] < minD) { minD = dist[i]; minI = i; }
        vis[minI] = true; total += minD;
        for (int i = 0; i < n; i++) if (!vis[i]) dist[i] = min(dist[i], abs(points[minI][0]-points[i][0]) + abs(points[minI][1]-points[i][1]));
    }
    return total;
}
